PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS roles(id INTEGER PRIMARY KEY AUTOINCREMENT,source_number INTEGER UNIQUE NOT NULL,tier TEXT NOT NULL,company TEXT NOT NULL,title TEXT NOT NULL,location TEXT NOT NULL,experience TEXT NOT NULL,fit_summary TEXT NOT NULL,apply_url TEXT NOT NULL,notes TEXT,status TEXT NOT NULL DEFAULT 'not_started',match_score INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pipeline_history(id INTEGER PRIMARY KEY AUTOINCREMENT,role_id INTEGER NOT NULL,from_status TEXT,to_status TEXT NOT NULL,changed_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS resume_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,target_company TEXT,target_role TEXT,content TEXT NOT NULL,fact_guard TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analyses(id INTEGER PRIMARY KEY AUTOINCREMENT,company TEXT,job_title TEXT,source_url TEXT,raw_description TEXT NOT NULL,requirements TEXT NOT NULL,coverage TEXT NOT NULL,overall_score INTEGER NOT NULL,provider TEXT NOT NULL,model TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
